---
import { renderLumenCodeHtml, renderLumenIconSvg, resolveLumenAstroProps } from '@santi020k/lumen-core'

import type { HTMLAttributes } from 'astro/types'

type CodeTheme = 'auto' | 'lumen' | 'santi020k'
type CodeVariant = 'block' | 'inline'

interface Props extends HTMLAttributes<'code'> {
  class?: string
  className?: string
  code?: string
  copy?: boolean
  highlighted?: boolean
  label?: string
  language?: string
  theme?: CodeTheme
  variant?: CodeVariant
}

const {
  class: classProp = '',
  className = '',
  code,
  copy = false,
  highlighted = false,
  label,
  language,
  theme = 'auto',
  variant = 'inline',
  ...rest
} = Astro.props

const { classList: blockClassList, passthrough } = resolveLumenAstroProps(rest, [
  'ui-code',
  'ui-code--block'
], classProp, className)
const { classList: inlineClassList } = resolveLumenAstroProps(rest, [
  'ui-code',
  'ui-code--inline'
], classProp, className)
const shouldShowHeader = variant === 'block' && Boolean(copy || label || language)
const hasCode = code !== undefined
const renderedCode = hasCode ? renderLumenCodeHtml(code, language) : ''
---

{variant === 'block' ? (
  <figure
    class:list={blockClassList}
    data-code-theme={theme}
    data-language={language}
    data-ui-code
    {...passthrough}
  >
    {shouldShowHeader && (
      <figcaption class="ui-code__header">
        <span class="ui-code__dots" aria-hidden="true">
          <span class="ui-code__dot ui-code__dot--red"></span>
          <span class="ui-code__dot ui-code__dot--yellow"></span>
          <span class="ui-code__dot ui-code__dot--green"></span>
        </span>
        <span class="ui-code__meta">
          {language && <span class="ui-code__language">{language}</span>}
          {label && <span class="ui-code__label">{label}</span>}
        </span>
        {copy && (
          <button
            aria-label="Copy code to clipboard"
            class="ui-code__copy"
            data-ui-code-copy
            type="button"
          >
            <Fragment set:html={renderLumenIconSvg('copy', { className: 'ui-code__copy-icon' })} />
            <Fragment set:html={renderLumenIconSvg('check', { className: 'ui-code__check-icon' })} />
          </button>
        )}
      </figcaption>
    )}
    {highlighted ? (
      <slot />
    ) : hasCode ? (
      <pre><code set:html={renderedCode}></code></pre>
    ) : (
      <pre><code><slot /></code></pre>
    )}
  </figure>
) : (
  <code
    class:list={inlineClassList}
    data-code-theme={theme}
    data-language={language}
    {...passthrough}
  >
    {hasCode ? code : <slot />}
  </code>
)}

---
import { resolveLumenAstroProps } from '@santi020k/lumen-core'

import type { HTMLAttributes } from 'astro/types'

interface Props extends HTMLAttributes<'input'> {
  class?: string
  className?: string
  label?: string
  list: string
  options?: ComboboxOption[]
}

interface Option {
  disabled?: boolean
  label: string
  value: string
}

type ComboboxOption = Option | string

const {
  class: classProp = '',
  className = '',
  id,
  label,
  list,
  options = [],
  type = 'text',
  ...rest
} = Astro.props

const inputId = id ?? `${list}-input`
const normalizedOptions = options.map(option =>
  typeof option === 'string' ? { label: option, value: option } : option
)
const { classList, passthrough } = resolveLumenAstroProps(rest, ['ui-combobox'
], classProp, className)
---

<div class:list={classList} data-ui-combobox>
  {label && <label class="ui-label" for={inputId}>{label}</label>}
  <input
    aria-autocomplete="list"
    aria-controls={list}
    aria-expanded="false"
    class="ui-input"
    id={inputId}
    role="combobox"
    type={type}
    {...passthrough}
  />
  <div class="ui-combobox__list" hidden id={list} role="listbox">
    {normalizedOptions.map(option => (
      <button
        aria-disabled={option.disabled ? 'true' : undefined}
        data-ui-combobox-option
        data-value={option.value}
        disabled={option.disabled}
        role="option"
        type="button"
      >
        {option.label}
      </button>
    ))}
  </div>
</div>

